        Token::Blockquote | Token::Svg | Token::Path | Token::Rect | Token::Circle |
        Token::Ellipse | Token::Line | Token::Polyline | Token::Group | Token::Defs |
        Token::Text | Token::SvgImage | Token::Use | Token::Anchor | Token::Image |
        Token::Table | Token::TableCell | Token::TableRow | Token::Form | Token::Input |
        Token::TextArea | Token::Label => {
            let tag = match token {
                Token::Div => "div",
                Token::Span => "span",
                Token::Button => "button",
                Token::Section => "section",
                Token::Aside => "aside",
                Token::Paragraph => "p",
                Token::Heading => "h1",
                Token::UnorderedList => "ul",
                Token::ListItem => "li",
                Token::Blockquote => "blockquote",
                Token::Svg => "svg",
                Token::Path => "path",
                Token::Rect => "rect",
                Token::Circle => "circle",
                Token::Ellipse => "ellipse",
                Token::Line => "line",
                Token::Polyline => "polyline",
                Token::Group => "g",
                Token::Defs => "defs",
                Token::Text => "text",
                Token::SvgImage => "image",
                Token::Use => "use",
                Token::Anchor => "a",
                Token::Image => "img",
                Token::Table => "table",
                Token::TableCell => "td",
                Token::TableRow => "tr",
                Token::Form => "form",
                Token::Input => "input",
                Token::TextArea => "textarea",
                Token::Label => "label",
                _ => unreachable!(),
            };
            let mut i = start + 1;
            let mut classes = Vec::new();
            let mut attrs = Vec::new();
            while i < tokens.len() {
                match &tokens[i] {
                    Token::Class(c) => {
                        classes.push(c.clone());
                        i += 1;
                    }
                    Token::AttrName(name) => {
                        let name = name.clone();
                        i += 1;
                        if i < tokens.len() {
                            if let Token::QuotedValue(val) = &tokens[i] {
                                attrs.push((name, val.clone()));
                                i += 1;
                            } else if let Token::Ident(val) = &tokens[i] {
                                attrs.push((name, val.clone()));
                                i += 1;
                            }
                        }
                    }
                    Token::Newline => {
                        i += 1;
                        break;
                    }
                    _ => break,
                }
            }
            let mut children = Vec::new();
            if i < tokens.len() && matches!(tokens[i], Token::Newline) {
                let mut peek = i + 1;
                let mut child_indent = 0;
                if peek < tokens.len() {
                    if let Token::Whitespace(ws) = &tokens[peek] {
                        child_indent = ws.len();
                        peek += 1;
                    }
                }
                if child_indent > 0 {
                    i = peek;
                    while i < tokens.len() {
                        if matches!(tokens[i], Token::Newline) {
                            i += 1;
                            if i < tokens.len() {
                                if let Token::Whitespace(ws) = &tokens[i] {
                                    if ws.len() < child_indent {
                                        break;
                                    }
                                    i += 1;
                                } else {
                                    break;
                                }
                            }
                            continue;
                        }
                        let (child, next) = parse_node(tokens, i);
                        children.push(child);
                        i = next;
                    }
                }
            }
            (ASTNode::Element {
                tag: tag.to_string(),
                classes,
                attrs,
                children,
            }, i)
        }
        Token::Ident(text) => {
            (ASTNode::Text(text.clone()), start + 1)
        }
        Token::InterpolationOpen => {
            let mut content = String::new();
            let mut i = start + 1;
            while i < tokens.len() {
                match &tokens[i] {
                    Token::InterpolationClose => {
                        i += 1;
                        break;
                    }
                    Token::Ident(s) | Token::Class(s) => {
                        content.push_str(s);
                        i += 1;
                    }
                    _ => {
                        content.push_str(&format!("{:?}", tokens[i]));
                        i += 1;
                    }
                }
            }
            (ASTNode::Text(format!("{{{{{}}}}}", content)), i)
        }
        _ => {
            (ASTNode::Text(format!("<unknown: {:?}>", token)), start + 1)
        }
    }
}

fn emit_html(node: &ASTNode) -> String {
    match node {
        ASTNode::Element { tag, classes, attrs, children } => {
            let class_str = if classes.is_empty() {
                String::new()
            } else {
                format!(" class=\"{}\"", classes.join(" "))
            };
            let attrs_str = attrs.iter()
                .map(|(k, v)| format!(" {}=\"{}\"", k, v))
                .collect::<Vec<_>>()
                .join("");
            let children_html = children.iter().map(emit_html).collect::<Vec<_>>().join("");
            if is_void_element(tag) {
                format!("<{}{}{}/>", tag, class_str, attrs_str)
            } else {
                format!("<{}{}{}>{}</{}>", tag, class_str, attrs_str, children_html, tag)
            }
        }
        ASTNode::Text(text) => text.clone(),
    }
}

fn is_void_element(tag: &str) -> bool {
    matches!(tag, "br" | "img" | "input" | "hr")
}

