use crate::parser::ASTNode;

pub fn emit_leptos(node: &ASTNode) -> String {
    match node {
        ASTNode::Element { tag, classes, attrs, children } => {
            let class_str = if classes.is_empty() { String::new() }
                else { format!(" class=\"{}\"", classes.join(" ")) };
            let attrs_str = attrs.iter()
                .map(|(k, v)| {
                    // Convert on:click -> on:click
                    if k.starts_with("on:") || k.starts_with("on") {
                        format!(" {}=\"{}\"", k, v)
                    } else {
                        format!(" {}=\"{}\"", k, v)
                    }
                })
                .collect::<Vec<_>>().join("");
            let children_str = children.iter().map(emit_leptos).collect::<Vec<_>>().join("");
            if is_void(tag) {
                format!("<{}{}{}/>", tag, class_str, attrs_str)
            } else {
                format!("<{}{}{}>{}</{}>", tag, class_str, attrs_str, children_str, tag)
            }
        }
        ASTNode::Text(text) => {
            // Convert {{ title }} to {move || title.get()}
            if text.starts_with("{{") && text.ends_with("}}") {
                let inner = &text[2..text.len()-2];
                let inner = inner.trim();
                format!("{{move || {}.get()}}", inner)
            } else {
                text.clone()
            }
        }
    }
}

fn is_void(tag: &str) -> bool { matches!(tag, "br" | "img" | "input" | "hr") }
